import {beforeEngI01Schema,beforeAuthorizedBatch10IntegrationPins} from "./question-program-batch10-acceptance-test-support";
import {beforeProgramBatch9AcceptanceRelease,beforeProgramBatch9AcceptanceManifest,beforeProgramBatch9AcceptanceSourceBytes,beforeProgramBatch9AcceptanceCases,beforeProgramBatch9AcceptanceConcepts} from "./question-program-batch9-acceptance-test-support";
// Preserve every authoring-era exclusion/pin against its exact verified epoch.
// Batch9 independently asserts current accepted and still-withheld tuples.
const live=beforeProgramBatch9AcceptanceRelease(batch9ActiveRelease);
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { answerChoiceTimingRegistryEntrySchema, validateSyntheticClinicalRelease } from './schema';
import { SYNTHETIC_CLINICAL_RELEASE as batch9ActiveRelease } from './synthetic-content';
import * as anesthesia from './question-topic-anesthesia-analgesia-pharmacology-20261111';
import * as hernia from './question-topic-hernia-groin-20261111';
import program from '../../../docs/research/question-intraop-program-20261112.json';
// @ts-expect-error The existing offline advisory linter has no TypeScript declaration.
import { collectAuthoredMetadata, inventoryRelease } from '../../../tools/question-quality/bank.mjs';
import {
  INTRAOP_I11_PACKET as packet,
  INTRAOP_I11_DEFINITIONS as definitions,
  INTRAOP_I11_QUESTIONS as questions,
  INTRAOP_I11_CASES as cases,
  INTRAOP_I11_AUTHORING_CONCEPTS as concepts,
  INTRAOP_I11_CASE_REVIEWS as reviews,
  INTRAOP_I11_CLAIMS as claims,
  INTRAOP_I11_SOURCES as sources,
  INTRAOP_I11_SOURCE_LINKS as links,
  INTRAOP_I11_STATEMENT_MAPPINGS as mappings,
  INTRAOP_I11_TIMING_ENTRIES as timing,
  INTRAOP_I11_ORDER_PROPOSALS as orders,
  INTRAOP_I11_PROCEDURE_CONTEXT_PROPOSALS as procedureContexts,
  INTRAOP_I11_PREVIEW_RELEASE as preview,
  INTRAOP_I11_MANIFEST as manifest,
  INTRAOP_I11_REVIEW_REVISION as revision,
} from './question-intraop-anesthetic-intraoperative-crises-20261112';

const root = fileURLToPath(new URL('../../../', import.meta.url));
const digest = (value: unknown) => createHash('sha256').update(JSON.stringify(value)).digest('hex');
const sourceDigest = (path: string) => createHash('sha256').update(beforeAuthorizedBatch10IntegrationPins(beforeProgramBatch9AcceptanceSourceBytes(path === "packages/clinical-content/src/schema.ts" ? beforeEngI01Schema(readFileSync(join(root, path))) : readFileSync(join(root, path))))).digest('hex');
const assigned = program.taxonomy.find(t => t.slug === 'anesthetic-intraoperative-crises')!;
function objectHashes(rootValue: unknown) {
  const hashes = new Set<string>(), seen = new WeakSet<object>();
  function visit(value: unknown) {
    if (!value || typeof value !== 'object' || seen.has(value)) return;
    seen.add(value);
    hashes.add(digest(value));
    for (const child of Object.values(value)) visit(child);
  }
  visit(rootValue);
  return hashes;
}

describe('I11 explicit-import intraoperative crisis authoring sidecar', () => {
  it('validates every materialized case against the current strict schema', () => {
    const checked = validateSyntheticClinicalRelease(preview);
    expect(checked.cases).toHaveLength(3);
    expect(checked.cases.flatMap(c => c.decisionNodes)).toHaveLength(4);
    expect(checked.concepts).toHaveLength(4);
    expect(manifest).toMatchObject({ pipelinePassed: false, managerAccepted: false,
      clinicalApproval: false, publicReleaseAuthorized: false, liveAdmissionAuthorized: false });
    expect(manifest.keyOrderNotice).toContain('key shown first for review only');
  });

  it('audits the complete assigned exact inventory and separates held planning records', () => {
    expect(packet.assignment).toEqual(assigned);
    const ids = [...assigned.existingRelatedBankNodes.map(r => r.recordId),
      ...assigned.retainedRecordIds, ...assigned.authoringDefinitionRecordIds].sort();
    expect(packet.audit.map(r => r.recordId).sort()).toEqual(ids);
    expect(packet.audit).toHaveLength(126);
    expect(packet.auditProblems).toEqual([]);
    expect(packet.beforeSnapshots.map(r => r.inventoryRecordId).sort()).toEqual(ids);
    expect(packet.audit.filter(r => r.verdict === 'Keep')).toHaveLength(packet.counts.keep);
    expect(packet.audit.filter(r => r.verdict === null)).toHaveLength(packet.counts.heldPlanningDispositions);
    expect(packet.counts.keep + packet.counts.heldPlanningDispositions).toBe(126);
    for (const row of packet.audit) {
      expect(row.actualDefinitionSha256).toMatch(/^[a-f0-9]{64}$/);
      expect(row.integrationChangeAuthorized).toBe(false);
      expect(row.reason.length).toBeGreaterThan(80);
    }
  });

  it('preserves the exact before serializations and all captured source hashes', () => {
    for (const before of packet.beforeSnapshots) {
      expect(digest(before.definition), before.inventoryRecordId).toBe(before.expectedSha256);
      expect(before.actualSha256).toBe(before.expectedSha256);
    }
    for (const source of packet.baseline.sourceInputs) {
      const drift = packet.baseline.concurrentDrift.find(d => d.file === source.file);
      expect(sourceDigest(source.file), source.file).toBe(drift?.currentSha256 ?? source.sha256);
      if (drift) expect(drift.entrySha256).toBe(source.sha256);
    }
    expect(packet.baseline.drift).toEqual([]);
  });

  it('retains all twenty live node hashes and the six exact manager-accepted freezes', () => {
    for (const row of program.coverage.liveCoverage.filter(r => assigned.existingRelatedBankNodes.some(x => x.recordId === r.recordId))) {
      const c = live.cases.find(c => c.id === row.caseId)!;
      expect(c, row.caseId).toBeDefined();
      expect(digest(c)).toBe(row.caseSha256);
      expect(digest(c.decisionNodes.find(n => n.id === row.nodeId))).toBe(row.nodeSha256);
    }
    const exportedHashes = objectHashes({ anesthesia, hernia });
    expect(packet.freezeReferences).toHaveLength(6);
    for (const receipt of packet.freezeReferences) {
      const c = live.cases.find(c => c.id === receipt.caseId)!;
      const currentNode = c.decisionNodes.find(n => n.id === receipt.nodeId)!;
      const projection = packet.freezeReconciliations.find(r => r.questionVariantId === receipt.questionVariantId);
      if (projection) {
        expect(projection.status).toBe('preexisting_projection_difference_preserved_manager_reconciliation_needed');
        expect(projection.historicalRuntimeReceiptSha256).toBe(receipt.runtimeNodeSha256);
        expect(digest(currentNode)).toBe(projection.entryRuntimeSha256);
        const archivedSource = JSON.parse(projection.sourceNodeJson);
        expect(digest(archivedSource)).toBe(receipt.sourceNodeSha256);
        expect(currentNode).toEqual({ ...archivedSource,
          stem: archivedSource.stem.split('Evan').join('{patientName}'),
          currentUpdate: archivedSource.currentUpdate.split('Evan').join('{patientName}'),
        });
      } else {
        expect(digest(currentNode)).toBe(receipt.runtimeNodeSha256);
      }
      expect(exportedHashes.has(receipt.sourceQuestionSha256), receipt.questionVariantId).toBe(true);
      expect(exportedHashes.has(receipt.sourceNodeSha256), receipt.nodeId).toBe(true);
    }
    expect(packet.clinicalApprovalReceipts).toEqual([]);
  });

  it('adds fresh identities without scoring a previously parked or accepted construct again', () => {
    const oldQuestions = new Set([...program.coverage.liveCoverage, ...program.coverage.retainedCoverage,
      ...program.coverage.authoringDefinitions].map(r => r.questionVariantId));
    expect(new Set(questions.map(q => q.id)).size).toBe(4);
    expect(new Set(concepts.map(c => c.id)).size).toBe(4);
    for (const q of questions) expect(oldQuestions.has(q.id)).toBe(false);
    expect(questions.some(q => /last-lipid|mh-early-drug|mh-uneventful-recovery/.test(q.id))).toBe(false);
    for (const c of concepts) {
      expect(c.previousConceptId).toBeNull();
      expect(c.historyMigration).toContain('None');
      expect(['new_meaning', 'unchanged_meaning']).toContain(c.conceptMeaning);
    }
    expect(packet.rejectedAuthorTargets[0]!.status).toBe('not_authored_after_deletion_test');
  });

  it('keeps all new authored clinical records and finite profiles pending clinical review', () => {
    for (const record of [...questions, ...concepts, ...claims, ...sources, ...reviews]) {
      expect(record.reviewStatus).toBe('needs_clinician_review');
      expect(record.aiAssistedDrafting).toBe(true);
      expect(record.lastClinicianReview).toBeNull();
    }
    for (const review of reviews) expect(review.profileApproval).toBe('needs_clinician_review');
    expect(packet.ownerApprovalsNeeded[0]!.owner).toBe('Melissa Rowland');
  });

  it('uses the live OR encoding and an explicit procedure-family/resource hold', () => {
    const liveCases = cases.filter(c => c.requiredClinicalSetting === 'ambulatory_surgery');
    expect(liveCases).toHaveLength(2);
    for (const c of liveCases) {
      expect(c.earliestFacilityStage).toBe(3);
      expect(c.releasePointId).toBe('release.l3.ambulatory');
      expect(c.requiredCapabilityIds).toEqual(['capability.ambulatory_or', 'capability.staff.or_nurse', 'capability.periop_recovery']);
      expect(c.presentation).toContain("clinic's ASC OR");
      const proposed = procedureContexts.find(p => p.caseId === c.id)!;
      expect(proposed).toMatchObject({ procedureFamily: 'open_inguinal_hernia_repair',
        engineeringDependency: 'ENG-I01', admissionState: 'awaiting_eng_i01' });
      expect(c).not.toHaveProperty('procedureContext');
      expect(c).not.toHaveProperty('procedureFamily');
    }
    expect(packet.integrationDependencies.find(d => d.id === 'ENG-I01')!.appliesToCaseIds).toHaveLength(2);
  });

  it('keeps hospital equipment in the outside record rather than local capabilities', () => {
    const c = cases.find(c => c.id.includes('airway-fire-record'))!;
    expect(c.requiredClinicalSetting).toBe('clinic');
    expect(c.requiredCapabilityIds).toEqual([]);
    expect(c.presentation).toContain('is in clinic');
    expect(c.presentation).toContain('outside hospital tracheostomy anesthesia record');
    const review = reviews.find(r => r.caseId === c.id)!;
    expect(review).toMatchObject({ acuity: 'stable', recordedAcuity: 'obvious_emergency', educationalTier: 1 });
    expect(procedureContexts.find(p => p.caseId === c.id)).toMatchObject({ recordKind: 'anesthesia_record', engineeringDependency: null });
  });

  it('keeps fixed named adult profiles and complete separate tasks', () => {
    for (const [index, c] of cases.entries()) {
      const definition = definitions[index]!;
      expect(c.patientDisplayName).toBe(definition.name);
      expect(c.prototypeDemographics).toEqual({ ageYears: definition.ageYears, sexLabel: definition.sexLabel });
      expect(c.prototypeDemographics!.ageYears).toBeGreaterThanOrEqual(18);
      expect(c.approvedInstantiationProfiles).toHaveLength(1);
      expect(c.approvedInstantiationProfiles![0]!.prototypeDemographics).toEqual(c.prototypeDemographics);
      expect(c.chiefComplaint!.split(/\s+/).length).toBeLessThanOrEqual(5);
      expect(c.presentation).toContain('{patientName}');
      expect(c.presentation).toContain(`${definition.ageYears}-year-old`);
      for (const n of c.decisionNodes) expect(n.stem).toContain('{patientName}');
    }
  });

  it('randomizes each exact option mapping and supplies terminal dispositions', () => {
    for (const c of cases) for (const [index, n] of c.decisionNodes.entries()) {
      expect(n.shuffleAnswers).toBe(true);
      expect(n.answerChoices).toHaveLength(3);
      expect(n.answerChoices.filter(ch => ch.isCorrect)).toHaveLength(1);
      expect(new Set(n.answerChoices.map(ch => ch.id)).size).toBe(3);
      const q = questions.find(q => q.id === n.questionVariantId)!;
      for (const ch of [...n.answerChoices].reverse()) {
        const authored = q.answerChoices.find(a => a.id === ch.id)!;
        expect([ch.label, ch.isCorrect, ch.rationale]).toEqual([authored.label, authored.isCorrect, authored.rationale]);
      }
      expect(n.terminalDispositions).toHaveLength(index === c.decisionNodes.length - 1 ? 2 : 0);
    }
  });

  it('classifies every offered choice truthfully without executing treatments or tests', () => {
    expect(timing).toHaveLength(4);
    expect(orders).toHaveLength(4);
    for (const t of timing) {
      answerChoiceTimingRegistryEntrySchema.parse(t);
      expect(t.classification).toEqual({ kind: 'no_test' });
    }
    for (const c of cases) for (const n of c.decisionNodes) {
      expect(n.resultGateAfter).toBeNull();
      expect(n.answerChoices.every(ch => ch.serviceRequest === null)).toBe(true);
      const proposal = orders.find(o => o.nodeId === n.id)!;
      for (const ch of [...n.answerChoices].reverse()) {
        expect(proposal.choices.find(p => p.choiceId === ch.id)).toMatchObject({ choiceLabel: ch.label, timing: { kind: 'no_test' } });
      }
    }
    expect(packet.counts.offeredTestingChoices).toBe(0);
    expect(packet.integrationDependencies.find(d => d.id === 'ENG-I02-conditional')!.status)
      .toBe('not_required_for_this_observation_only_packet');
  });

  it('uses a consequential second update without teaching its key in the first feedback', () => {
    const pair = cases.find(c => c.decisionNodes.length === 2)!;
    expect(pair.decisionNodes.map(n => n.questionVariantId)).toEqual([
      'question.intraop.anesthetic-intraoperative-crises.anaphylaxis-first-drug.v1',
      'question.intraop.anesthetic-intraoperative-crises.anaphylaxis-infusion.v1',
    ]);
    expect(pair.decisionNodes[0]!.explanation).not.toMatch(/infusion|norepinephrine/i);
    expect(pair.decisionNodes[1]!.currentUpdate).toContain('fall again between boluses');
    expect(pair.decisionNodes[1]!.resultGateAfter).toBeNull();
    expect(packet.selectorLimitation).toContain('future-due companion');
    const mh = cases.find(c => c.id.includes('mh-electrolyte'))!;
    expect(mh.decisionNodes[0]!.exhibit?.kind).toBe('keyValue');
    expect(mh.decisionNodes[0]!.currentUpdate).toContain('is being administered');
  });

  it('records concrete five-check reviews, counterfactuals and the honest rule exceptions', () => {
    const nodes = definitions.flatMap(c => c.nodes);
    for (const n of nodes) {
      for (const field of ['interpret', 'apply', 'closestError', 'decidingObservation', 'counterfactual',
        'cueAttack', 'stageAndCategory', 'difficultyReason', 'deletionTest', 'sequenceAudit', 'oneBestAnswer',
        'finiteProfileCheck', 'separateTaskCheck']) {
        expect(String(n.authorGate[field]).length, `${n.id}: ${field}`).toBeGreaterThan(30);
      }
      for (const ch of n.choices.filter(ch => ch.id !== n.key)) {
        expect(ch.temptation.length).toBeGreaterThan(30);
        expect(ch.counterfactual.length).toBeGreaterThan(30);
      }
    }
    expect(nodes.filter(n => n.authorGate.reasoningType === 'clean_rule_recall_exception')).toHaveLength(2);
    expect(nodes.filter(n => n.authorGate.reasoningType === 'two_consequential_steps')).toHaveLength(2);
    expect(nodes.every(n => n.authorGate.pipelinePassed === false)).toBe(true);
  });

  it('maps every claim and choice to permitted sources while preserving disagreements', () => {
    const claimIds = new Set(claims.map(c => c.id)), sourceIds = new Set(sources.map(s => s.id));
    expect(mappings.map(m => m.questionVariantId).sort()).toEqual(questions.map(q => q.id).sort());
    for (const q of questions) for (const id of q.supportingEvidenceClaimIds) expect(claimIds.has(id)).toBe(true);
    for (const n of definitions.flatMap(c => c.nodes)) for (const ch of n.choices) {
      expect(ch.claimIds.length).toBeGreaterThan(0);
      ch.claimIds.forEach(id => expect(claimIds.has(id)).toBe(true));
    }
    for (const claim of claims) {
      expect(claim.sourceIds.length).toBeGreaterThan(0);
      expect(claim.lastCheckedOn).toBe('2026-11-12');
      for (const id of claim.sourceIds) {
        expect(sourceIds.has(id)).toBe(true);
        expect(sources.find(s => s.id === id)!.evidenceClaimIds).toContain(claim.id);
      }
      if (claim.sourceIds.length === 1) expect(claim.limitation).toBeTruthy();
    }
    for (const s of sources) {
      expect(s.completeCitation.length).toBeGreaterThan(60);
      expect(s.authorityAssessment.length).toBeGreaterThan(40);
      expect(s.reuseNotes.length).toBeGreaterThan(80);
      expect(s.officialUrl).toMatch(/^https:\/\//);
      expect(s.id).not.toMatch(/mhaus/);
    }
    const ledger = JSON.parse(readFileSync(join(root, 'docs/research/sources-question-intraop-anesthetic-intraoperative-crises-20261112.json'), 'utf8'));
    expect(ledger.excludedSources[0].disposition).toBe('excluded_after_rights_check');
    expect(ledger.disagreements).toHaveLength(3);
    expect(ledger.disagreements.every((d: { disposition: string }) => d.disposition === 'withheld_not_scored')).toBe(true);
  });

  it('opens source links safely and keeps gameplay data compiled and sidecar-only', () => {
    for (const link of links) expect(link).toMatchObject({ target: '_blank', rel: 'noopener noreferrer', referrerPolicy: 'no-referrer' });
    expect(live.cases.some(c => cases.some(draft => draft.id === c.id))).toBe(false);
    const implementation = readFileSync(join(root, 'packages/clinical-content/src/question-intraop-anesthetic-intraoperative-crises-20261112.ts'), 'utf8');
    expect(implementation).not.toMatch(/\bfetch\s*\(|https?:\/\//);
    for (const file of ['docs/research/question-intraop-anesthetic-intraoperative-crises-20261112.json',
      'docs/research/sources-question-intraop-anesthetic-intraoperative-crises-20261112.json']) {
      expect(() => JSON.parse(readFileSync(join(root, file), 'utf8'))).not.toThrow();
    }
  });

  it('runs the actual advisory cue linter on every owned canonical and finite-profile sequence', () => {
    const report = inventoryRelease(preview, collectAuthoredMetadata({ questions, concepts, reviews, claims, sources }));
    expect(report.totals.uniqueVariants).toBe(4);
    expect(report.totals.profileContexts).toBe(8);
    expect(report.totals.variantsWithCompleteRationales).toBe(4);
    expect(report.variants.flatMap((v: { questionVariantId: string; findings: unknown[] }) =>
      v.findings.map(f => ({ id: v.questionVariantId, finding: f })))).toEqual([]);
    expect(report.totals.findings).toBe(0);
  });

  it('answers every independent note and makes exactly one attempt per returned identity', () => {
    expect(packet.revisionRound).toBe(1);
    expect(sourceDigest(revision.reviewPath)).toBe(revision.reviewFileSha256);
    expect(revision.dispositions).toHaveLength(4);
    expect(revision.dispositions.filter(d => d.status === 'pass-preserved')).toHaveLength(1);
    expect(revision.dispositions.filter(d => d.status === 'revised_pending_independent_recheck')).toHaveLength(3);
    expect(revision.dispositions.flatMap(d => d.noteResponses)).toHaveLength(44);
    for (const d of revision.dispositions) {
      const original = revision.originalReview.find(r => r.id === d.questionVariantId)!;
      expect(d.reviewVerdict).toBe(original.verdict);
      expect(d.repairAttempts).toBe(original.verdict === 'PASS' ? 0 : 1);
      expect(d.idsChanged).toBe(false);
      for (const kind of ['clarityIssues', 'cues', 'fairness', 'suggestions'] as const) {
        const answers = d.noteResponses.filter(n => n.kind === kind);
        expect(answers).toHaveLength(original[kind].length);
        for (const [index, note] of original[kind].entries()) {
          const answer = answers.find(a => a.index === index)!;
          expect(answer.reviewerNote).toEqual(note);
          expect(answer.response.length).toBeGreaterThan(60);
        }
      }
      const raw = definitions.flatMap(c => c.nodes).find(n => n.questionVariantId === d.questionVariantId)!;
      const question = questions.find(q => q.id === d.questionVariantId)!;
      expect(question.contentVersion).toBe(d.afterContentVersion);
      expect(question.reviewStatus).toBe('needs_clinician_review');
      if (original.verdict !== 'PASS') {
        expect(raw.contentVersion).toBe('question-intraop-anesthetic-intraoperative-crises.2026-11-12.v1.r1');
        expect(raw.conceptMeaning).toBe('unchanged_meaning');
      }
    }
    expect(questions.map(q => q.id).sort()).toEqual(revision.originalArtifacts.questions.map(q => q.id).sort());
    expect(cases.map(c => c.id).sort()).toEqual(revision.originalArtifacts.cases.map(c => c.id).sort());
    expect(concepts.map(c => c.id).sort()).toEqual(revision.originalArtifacts.authoringConcepts.map(c => c.id).sort());
    for (const n of definitions.flatMap(c => c.nodes)) {
      const before = revision.originalProposedCases.flatMap(c => c.nodes).find(b => b.id === n.id)!;
      expect(n.choices.map(c => c.exactChoiceId)).toEqual(before.choices.map(c => c.exactChoiceId));
    }
  });

  it('freezes the exact PASS question, node, raw definition, concept and timing/order mappings', () => {
    expect(revision.frozenPass).toHaveLength(1);
    for (const receipt of revision.frozenPass) {
      const beforeRaw = revision.originalProposedCases.flatMap(c => c.nodes).find(n => n.questionVariantId === receipt.questionVariantId)!;
      const currentRaw = definitions.flatMap(c => c.nodes).find(n => n.questionVariantId === receipt.questionVariantId)!;
      const beforeQuestion = revision.originalArtifacts.questions.find(q => q.id === receipt.questionVariantId)!;
      const currentQuestion = questions.find(q => q.id === receipt.questionVariantId)!;
      const beforeCase = revision.originalArtifacts.cases.find(c => c.id === receipt.caseId)!;
      const beforeNode = beforeCase.decisionNodes.find(n => n.id === receipt.nodeId)!;
      const currentNode = cases.find(c => c.id === receipt.caseId)!.decisionNodes.find(n => n.id === receipt.nodeId)!;
      expect(currentRaw).toEqual(beforeRaw);
      expect(digest(currentRaw)).toBe(receipt.rawNodeSha256);
      expect(currentQuestion).toEqual(beforeQuestion);
      expect(digest(currentQuestion)).toBe(receipt.questionSha256);
      expect(currentNode).toEqual(beforeNode);
      expect(digest(currentNode)).toBe(receipt.runtimeNodeSha256);
      expect(digest(beforeCase)).toBe(receipt.sourceVisibleCaseSha256);
      expect(concepts.find(c => c.id === currentNode.primaryConceptId)).toEqual(
        revision.originalArtifacts.authoringConcepts.find(c => c.id === currentNode.primaryConceptId));
      expect(timing.find(t => t.nodeId === receipt.nodeId)).toEqual(
        revision.originalArtifacts.timing.find(t => t.nodeId === receipt.nodeId));
      expect(orders.find(t => t.nodeId === receipt.nodeId)).toEqual(
        revision.originalArtifacts.orders.find(t => t.nodeId === receipt.nodeId));
    }
  });

  it('limits the PASS companion-context repair and preserves preceding feedback without scaffolding', () => {
    expect(revision.contextChanges).toHaveLength(1);
    const change = revision.contextChanges[0]!;
    const before = revision.originalArtifacts.cases.find(c => c.id === change.caseId)!;
    const after = cases.find(c => c.id === change.caseId)!;
    expect(change).toMatchObject({ frozenPassDecisionChanged: false, sourcePatientDemographicsChanged: false,
      priorFeedbackChanged: false, status: 'revised_full_sequence_pending_independent_recheck' });
    expect(after.presentation).toContain('during induction, before skin incision');
    expect(after.presentation).toContain('initial incision');
    expect(after).toEqual({ ...before, presentation: after.presentation,
      approvedInstantiationProfiles: before.approvedInstantiationProfiles!.map(profile => ({ ...profile, presentation: after.presentation })),
      sourceLabels: after.sourceLabels, decisionNodes: [after.decisionNodes[0], before.decisionNodes[1]],
    });
    expect(after.decisionNodes[0]!.explanation).toBe(before.decisionNodes[0]!.explanation);
    expect(after.decisionNodes[0]!.stem).toContain('paused');
    expect(after.decisionNodes[0]!.explanation).not.toMatch(/infusion|norepinephrine|continuous/i);
    const mh = definitions.flatMap(c => c.nodes).find(n => n.slug === 'mh-potassium-cardiotoxicity')!;
    expect(mh.task).not.toMatch(/occupied-OR|current OR checkpoint|additional|MH response/);
    expect(mh.choices.map(c => c.label)).toEqual(['Give calcium gluconate', 'Defer calcium gluconate', 'Use sodium bicarbonate']);
    expect(JSON.stringify(mh.exhibit)).toContain('calcium-channel blockers');
    const fire = cases.find(c => c.id.includes('airway-fire-record'))!;
    expect(fire.presentation).toContain('oral endotracheal tube');
    expect(fire.presentation).toContain('through the opening');
    expect(fire.decisionNodes[0]!.answerChoices.some(c => /exchange catheter/.test(c.label))).toBe(true);
    expect(fire.decisionNodes[0]!.answerChoices.some(c => /^Advance/.test(c.label))).toBe(false);
    expect(packet.quality.ruleExceptionsPendingExactPurposeAcceptance).toHaveLength(2);
  });
});

// BEGIN BATCH9 STANDALONE SALVAGE 20261113
import * as salvageLane from './question-intraop-anesthetic-intraoperative-crises-20261112';
import { createHash as salvageCreateHash } from 'node:crypto';
import { readFileSync as salvageReadFile } from 'node:fs';
import { syntheticClinicalCaseSchema as salvageCaseSchema } from './schema';
const salvageDraft = salvageLane.INTRAOP_I11_SALVAGE;
const salvageCases = salvageLane.INTRAOP_I11_SALVAGE_CASES;
const salvageMetadata = salvageLane.INTRAOP_I11_SALVAGE_METADATA;
const salvagePreview = salvageLane.INTRAOP_I11_SALVAGE_PREVIEW_RELEASE;
const salvageRoot = new URL('../../../', import.meta.url);
const salvageRead = (path: string) => salvageReadFile(new URL(path, salvageRoot), 'utf8');
const salvageHash = (value: unknown) => salvageCreateHash('sha256').update(typeof value === 'string' ? value : JSON.stringify(value)).digest('hex');
const salvageSourceCases = [...salvageLane.INTRAOP_I11_CASES];
const salvageSourceTimings = [...salvageLane.INTRAOP_I11_TIMING_ENTRIES];
const salvageSourceOrders = [...salvageLane.INTRAOP_I11_ORDER_PROPOSALS];

describe('Batch9 standalone salvage: anesthetic-intraoperative-crises', () => {
  it('preserves every original export, historical packet field and source/document preimage', () => {
    const expectedExports = ['INTRAOP_I11_SALVAGE', 'INTRAOP_I11_SALVAGE_CASES', 'INTRAOP_I11_SALVAGE_METADATA', 'INTRAOP_I11_SALVAGE_PREVIEW_RELEASE', 'INTRAOP_I11_SALVAGE_TIMING_ENTRIES'].sort();
    expect(Object.keys(salvageLane).filter(name => name.startsWith('INTRAOP_I11_SALVAGE')).sort()).toEqual(expectedExports);
    const originalExports = Object.fromEntries(Object.entries(salvageLane).sort(([left], [right]) => left < right ? -1 : left > right ? 1 : 0).filter(([name]) => !name.startsWith('INTRAOP_I11_SALVAGE')).map(([name, value]) => [name, (name === 'INTRAOP_I11_PACKET' ? Object.fromEntries(Object.entries(value as Record<string, unknown>).filter(([key]) => key !== 'salvage')) : value)]));
    expect(salvageHash(originalExports)).toBe(salvageDraft.preservation.originalExportsSha256);
    const originalPacket = JSON.parse(salvageRead('docs/research/question-intraop-anesthetic-intraoperative-crises-20261112.json')) as Record<string, unknown>;
    delete originalPacket.salvage;
    expect(salvageHash(originalPacket)).toBe(salvageDraft.preservation.originalPacketContentSha256);
    expect(salvageHash(salvageRead('packages/clinical-content/src/question-intraop-anesthetic-intraoperative-crises-20261112.ts').split(salvageDraft.preservation.sourceMarker)[0])).toBe(salvageDraft.preservation.originalSourceSha256);
    expect(salvageHash(salvageRead('docs/research/question-intraop-anesthetic-intraoperative-crises-20261112.md').split(salvageDraft.preservation.markdownMarker)[0])).toBe(salvageDraft.preservation.originalMarkdownSha256);
  });

  it('contains only each requested PASS decision with exact scored bytes and explicit final closure', () => {
    expect(salvageDraft.definitions.map(spec => spec.nodeId)).toEqual(["node.intraop.anesthetic-intraoperative-crises.anaphylaxis-infusion.v1"]);
    expect(salvageCases).toHaveLength(1);
    expect(salvageMetadata.questions).toEqual(salvageDraft.questions);
    expect(salvageMetadata.concepts).toEqual(salvageDraft.authoringConcepts);
    for (const spec of salvageDraft.definitions) {
      const prior = salvageSourceCases.find(value => value.id === spec.sourceCaseId && value.decisionNodes.some(node => node.id === spec.nodeId))!;
      const passed = prior.decisionNodes.find(node => node.id === spec.nodeId)!;
      const clinicalCase = salvageCases.find(value => value.id === spec.caseId)!;
      const node = clinicalCase.decisionNodes[0]!;
      expect(() => salvageCaseSchema.parse(clinicalCase)).not.toThrow();
      expect(clinicalCase.id).toBe(spec.sourceCaseId.replace(/\.v1$/, '-salvage.v1'));
      expect(clinicalCase.id).toMatch(/-salvage\.v1$/);
      expect(clinicalCase.decisionNodes).toHaveLength(1);
      expect(salvageHash(prior)).toBe(spec.sourceCaseSha256);
      expect(salvageHash(passed)).toBe(spec.sourceNodeSha256);
      expect(salvageHash(clinicalCase)).toBe(spec.salvageCaseSha256);
      expect(salvageHash(salvageLane.INTRAOP_I11_QUESTIONS.find(value => value.id === spec.questionVariantId))).toBe(spec.sourceQuestionSha256);
      expect(salvageHash(salvageLane.INTRAOP_I11_TESTED_CONCEPTS.find(value => value.id === spec.conceptId))).toBe(spec.sourceConceptSha256);
      expect(salvageHash(salvageLane.INTRAOP_I11_AUTHORING_CONCEPTS.find(value => value.id === spec.conceptId))).toBe(spec.sourceAuthoringConceptSha256);
      expect(spec.contextExhibitChanges).toEqual([]);
      const expectedNode = structuredClone(passed);
      for (const change of spec.contextExhibitChanges as Array<{ row: number; column: number; before: string; after: string }>) {
        if (expectedNode.exhibit?.kind !== 'table') throw new Error('Expected the preserved table context');
        expect(expectedNode.exhibit.cells[change.row]![change.column]).toBe(change.before);
        expectedNode.exhibit.cells[change.row]![change.column] = change.after;
      }
      expectedNode.terminalDispositions = node.terminalDispositions;
      expect(node).toMatchObject(expectedNode);
      expect(node.answerChoices).toEqual(passed.answerChoices);
      expect(node.stem).toBe(passed.stem); expect(node.explanation).toBe(passed.explanation);
      expect(node.shuffleAnswers).toBe(true); expect(node.resultGateAfter).toBeNull();
      expect(node.answerChoices.filter(value => value.isCorrect)).toHaveLength(1);
      expect(node.answerChoices.every(value => value.serviceRequest === null)).toBe(true);
      expect(node.terminalDispositions.map(value => value.answerChoiceId).sort()).toEqual(node.answerChoices.filter(value => !value.isCorrect).map(value => value.id).sort());
      expect(node.terminalDispositions.every(value => value.kind === 'no_terminal_outcome')).toBe(true);
      expect(clinicalCase.learningSummary).toBe(passed.explanation);
      expect(spec.blockedByNodeIds.some(id => clinicalCase.decisionNodes.some(value => value.id === id))).toBe(false);
      expect(salvageHash(salvageRead(spec.passReview.path))).toBe(spec.passReview.sha256);
      expect(spec.passReview.verdict).toBe('PASS');
    }
  });

  it('keeps the setting, family, patient and completed-fact context self-contained and unapproved', () => {
    expect(salvageDraft.reviewStatus).toBe('needs_clinician_review');
    expect(salvageDraft.managerAccepted).toBe(false); expect(salvageDraft.clinicalApproval).toBe(false);
    expect(salvagePreview.publicationStatus).toBe('synthetic_unapproved_prototype');
    expect(salvageDraft.cases).toEqual(salvageCases);
    for (const spec of salvageDraft.definitions) {
      const clinicalCase = salvageCases.find(value => value.id === spec.caseId)!;
      const prior = salvageSourceCases.find(value => value.id === spec.sourceCaseId && value.decisionNodes.some(node => node.id === spec.nodeId))!;
      expect(clinicalCase.prototypeDemographics).toEqual(prior.prototypeDemographics);
      expect(clinicalCase.patientDisplayName).toBe(prior.patientDisplayName);
      expect(clinicalCase.requiredClinicalSetting).toBe(prior.requiredClinicalSetting);
      expect(clinicalCase.requiredCapabilityIds).toEqual(prior.requiredCapabilityIds);
      expect(clinicalCase.earliestFacilityStage).toBe(prior.earliestFacilityStage);
      expect(clinicalCase.releasePointId).toBe(prior.releasePointId);
      expect(clinicalCase.routineEligible).toBe(false); expect(clinicalCase.tutorialEligible).toBe(false);
      expect(clinicalCase.approvedInstantiationProfiles).toHaveLength(1);
      const profile = clinicalCase.approvedInstantiationProfiles![0]!;
      expect(profile.id).toBe(spec.profileId);
      expect(profile.prototypeDemographics).toEqual(prior.approvedInstantiationProfiles![0]!.prototypeDemographics);
      expect(profile.presentation).toBe(clinicalCase.presentation);
      const sourceContext = salvageLane.INTRAOP_I11_PROCEDURE_CONTEXT_PROPOSALS.find(value => value.caseId === spec.sourceCaseId)!;
      expect(salvageHash(sourceContext)).toBe(spec.sourceProcedureContextSha256);
      const { salvageNodeId, salvagePhase, ...context } = salvageDraft.procedureContextProposals.find(value => value.caseId === spec.caseId)!;
      expect({ ...context, caseId: spec.sourceCaseId }).toEqual(sourceContext);
      expect(salvageNodeId).toBe(spec.nodeId); expect(salvagePhase).toContain("completed observations");
      const review = salvageDraft.caseReviews.find(value => value.caseId === spec.caseId)!;
      expect(review.reviewStatus).toBe('needs_clinician_review');
      expect(review.profileReviewStatus).toBe('needs_clinician_review');
      expect(review.educationalTier).toBeTypeOf("number"); expect(review.acuity).toBeTruthy();
      expect(spec.evidenceClaimIds.length).toBeGreaterThan(0);
      for (const id of spec.evidenceClaimIds) expect(salvageMetadata.claims.some(value => value.id === id)).toBe(true);
      for (const id of spec.sourceIds) expect(salvageMetadata.sources.some(value => value.id === id)).toBe(true);
      expect(salvageDraft.familyContexts).toEqual([]);
    }
  });

  it('retains every exact choice-timing and unexecuted order mapping under the salvage case ID', () => {
    expect(salvageLane.INTRAOP_I11_SALVAGE_TIMING_ENTRIES).toHaveLength(salvageCases.length);
    for (const spec of salvageDraft.definitions) {
      const source = salvageSourceTimings.find(value => value.caseId === spec.sourceCaseId && value.nodeId === spec.nodeId)!;
      const timing = salvageLane.INTRAOP_I11_SALVAGE_TIMING_ENTRIES.find(value => value.caseId === spec.caseId)!;
      expect({ ...timing, caseId: spec.sourceCaseId }).toEqual(source);
      if (timing.classification.kind === "test_choices") {
        const node = salvageCases.find(value => value.id === spec.caseId)!.decisionNodes[0]!;
        expect(timing.classification.choices.map(value => [value.choiceId, value.choiceLabel])).toEqual(node.answerChoices.map(value => [value.id, value.label]));
      }
      for (const proposal of (salvageDraft.orderProposals as Array<{ caseId: string; [key: string]: unknown }>).filter(value => value.caseId === spec.caseId)) {
        expect(salvageSourceOrders.some(value => salvageHash(value) === salvageHash({ ...proposal, caseId: spec.sourceCaseId }))).toBe(true);
      }
    }
  });

  it('runs the full cue scanner on every canonical and finite-profile salvage context with zero findings', async () => {
    const { collectAuthoredMetadata, inventoryRelease } = await import(new URL('tools/question-quality/bank.mjs', salvageRoot).href);
    const report = inventoryRelease(salvagePreview, collectAuthoredMetadata(salvageMetadata));
    expect(report.totals).toEqual(salvageDraft.cueLint.totals);
    expect(report.totals).toMatchObject({ cases: 1, uniqueVariants: 1, profileContexts: 2, findings: 0, variantsWithFindings: 0, missingAuthoredVersion: 0, missingEducationalTier: 0, variantsWithCompleteRationales: 1 });
    expect(report.variants.flatMap((value: { findings: unknown[] }) => value.findings)).toEqual([]);
    expect(salvageDraft.cueLint.suppressions).toEqual([]);
  });
});
// END BATCH9 STANDALONE SALVAGE 20261113

import {beforeProgramBatch9AcceptanceRelease,beforeProgramBatch9AcceptanceManifest,beforeProgramBatch9AcceptanceSourceBytes,beforeProgramBatch9AcceptanceCases,beforeProgramBatch9AcceptanceConcepts} from "./question-program-batch9-acceptance-test-support";
// Preserve every authoring-era exclusion/pin against its exact verified epoch.
// Batch9 independently asserts current accepted and still-withheld tuples.
const SYNTHETIC_CLINICAL_RELEASE=beforeProgramBatch9AcceptanceRelease(batch9ActiveRelease);
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  answerChoiceTimingRegistryEntrySchema,
  decisionNodeSchema,
  syntheticClinicalCaseSchema,
  testedConceptSchema,
} from "./schema";
import { SYNTHETIC_CLINICAL_RELEASE as batch9ActiveRelease } from "./synthetic-content";
import {
  INTRAOP_ANORECTAL_PACKET as packet,
  INTRAOP_ANORECTAL_SOURCE_LEDGER as ledger,
  INTRAOP_ANORECTAL_QUESTIONS as questions,
  INTRAOP_ANORECTAL_NODES as nodes,
  INTRAOP_ANORECTAL_CASES as cases,
  INTRAOP_ANORECTAL_TESTED_CONCEPTS as concepts,
  INTRAOP_ANORECTAL_CONCEPT_PROPOSALS as conceptProposals,
  INTRAOP_ANORECTAL_CASE_REVIEWS as caseReviews,
  INTRAOP_ANORECTAL_SOURCES as sources,
  INTRAOP_ANORECTAL_CLAIMS as claims,
  INTRAOP_ANORECTAL_TIMING_ENTRIES as timings,
  INTRAOP_ANORECTAL_ORDER_PROPOSALS as orders,
  INTRAOP_ANORECTAL_PROCEDURE_CONTEXT_PROPOSALS as procedureContexts,
  INTRAOP_ANORECTAL_RETAINED_TIMING_ENTRIES as retainedTimings,
  INTRAOP_ANORECTAL_RETAINED_ORDER_PROPOSALS as retainedOrders,
  INTRAOP_ANORECTAL_INTEGRATION as integration,
} from "./question-intraop-anorectal-eua-and-fistula-20261112";

const root = new URL("../../../", import.meta.url);
const read = (path: string) => beforeProgramBatch9AcceptanceSourceBytes(readFileSync(new URL(path, root), "utf8"));
const sha = (text: string) => createHash("sha256").update(text).digest("hex");
const digest = (value: unknown) => sha(JSON.stringify(value));

describe("I09 anorectal EUA explicit-import authoring sidecar", () => {
  it("pins round 1 review and responds exactly once to every original note", () => {
    const round = packet.revisionRound1;
    expect(packet.revisionRound).toBe(1);
    expect(sha(read(round.reviewFile))).toBe(round.reviewSha256);
    const review = JSON.parse(read(round.reviewFile)) as Array<{
      id: string; nodeId: string; verdict: string;
      clarityIssues: string[]; cues: Array<{ phrase: string; why: string }>;
      fairness: string[]; suggestions: string[];
    }>;
    const expected = review.flatMap((row) => (["clarityIssues", "cues", "fairness", "suggestions"] as const)
      .flatMap((category) => row[category].map((originalNote, index) => ({
        noteId: `${row.id}.${category}.${index + 1}`,
        questionVariantId: row.id,
        nodeId: row.nodeId,
        inputVerdict: row.verdict,
        category,
        index: index + 1,
        originalNote,
      }))));
    expect(round.inputDispositionCounts).toEqual({ PASS: 1, REVISE: 2, FAIL: 0 });
    expect(expected).toHaveLength(36);
    expect(new Set(round.noteResponses.map((row) => row.noteId)).size).toBe(36);
    expect(round.noteResponses.map(({ response: _response, ...row }) => row)).toEqual(expected);
    expect(round.noteCounts).toEqual({ total: 36, returned: 27, pass: 9 });
    for (const note of round.noteResponses) {
      expect(note.response.action.length).toBeGreaterThan(100);
      expect(note.response.locations.length).toBeGreaterThan(0);
      expect(note.response.clinicalApprovalGranted).toBe(false);
    }
    expect(round.nodeDispositions.map((row) => row.attemptCount)).toEqual([1, 0, 1]);
  });

  it("preserves the PASS definition, concept and complete preceding visible context exactly", () => {
    const round = packet.revisionRound1;
    expect(round.passFreeze).toHaveLength(1);
    for (const frozen of round.passFreeze) {
      const question = questions.find((question) => question.id === frozen.questionVariantId)!;
      const node = nodes.find((node) => node.id === frozen.nodeId)!;
      const clinicalCase = cases.find((clinicalCase) => clinicalCase.decisionNodes.some((node) => node.id === frozen.nodeId))!;
      const index = clinicalCase.decisionNodes.findIndex((node) => node.id === frozen.nodeId);
      const { decisionNodes, learningSummary: _learningSummary, ...header } = clinicalCase;
      const visible = { header, precedingNodes: decisionNodes.slice(0, index), node: decisionNodes[index] };
      expect(question).toEqual(frozen.question);
      expect(node).toEqual(frozen.node);
      expect(digest(question)).toBe(frozen.questionSha256);
      expect(digest(node)).toBe(frozen.nodeSha256);
      expect(visible).toEqual(frozen.visibleContext);
      expect(digest(visible)).toBe(frozen.visibleContextSha256);
      expect(conceptProposals.find((concept) => concept.id === node.primaryConceptId)).toEqual(frozen.conceptProposal);
      expect(question.contentVersion).toBe(round.snapshot.contentVersion);
    }
    expect(digest({ audit: packet.audit, contexts: packet.retainedContextSnapshots, registry: packet.registryHistory,
      freezes: packet.frozenReferences, holds: packet.historicalHolds })).toBe(round.preservedHistorySha256);
    for (const preimage of round.snapshot.sourcePreimages) expect(sha(preimage.text)).toBe(preimage.sha256);
  });

  it("versions the two returned definitions once and retains every identity and prior testing tuple", () => {
    const old = packet.revisionRound1.snapshot;
    expect(digest(old.reviewManifest.questions)).toBe(old.reviewManifest.questionsSha256);
    expect(digest(old.reviewManifest.nodes)).toBe(old.reviewManifest.nodesSha256);
    expect(digest(old.reviewManifest.cases)).toBe(old.reviewManifest.casesSha256);
    expect(questions.map((question) => question.id)).toEqual(old.reviewManifest.questions.map((question) => question.id));
    expect(nodes.map((node) => node.id)).toEqual(old.reviewManifest.nodes.map((node) => node.id));
    expect(cases.map((clinicalCase) => clinicalCase.id)).toEqual(old.reviewManifest.cases.map((clinicalCase) => clinicalCase.id));
    for (const question of questions) {
      const previous = old.reviewManifest.questions.find((previous) => previous.id === question.id)!;
      expect(question.conceptId).toBe(previous.conceptId);
      expect(question.answerChoices.map((choice) => choice.id)).toEqual(previous.answerChoices.map((choice) => choice.id));
      expect(question.answerChoices.find((choice) => choice.isCorrect)!.id).toBe(previous.answerChoices.find((choice) => choice.isCorrect)!.id);
      if (!packet.revisionRound1.passFreeze.some((record) => record.questionVariantId === question.id)) {
        expect(question.contentVersion).toBe(packet.contentVersion);
        expect(question.contentVersion).not.toBe(previous.contentVersion);
      }
    }
    expect(retainedTimings).toEqual(old.timingProposals);
    expect(retainedOrders).toEqual(old.testOrderProposals);
    for (const previous of old.sourceLedger.evidenceClaims) expect(claims.find((claim) => claim.id === previous.id)).toEqual(previous);
  });

  it("records the unresolved easy-role request and the revised diagnostic/chronology comparison", () => {
    const [safety, pass, sampling] = packet.proposedNodes;
    expect(safety!.currentUpdate).toContain("without a visible tract or communication");
    expect(safety!.choices.map((choice) => choice.label).join(" ")).not.toContain("toward the mucosal depression");
    expect(safety!.choices[0]!.label).toBe("Leave the incision open for drainage");
    expect(packet.revisionRound1.educationalRoleRequests[0]).toMatchObject({
      status: "pending_manager_and_independent_acceptance", basicAccepted: false, admissionHold: true,
    });
    expect(pass).toEqual(packet.revisionRound1.snapshot.proposedNodes[1]);
    expect(sampling!.task).not.toMatch(/additional sampling|which.*biops/i);
    expect(sampling!.currentUpdate).toContain("initial tract plan remains provisional");
    expect(sampling!.currentUpdate).not.toMatch(/focus in the wall of the fistula|separate from the sampled skin|preoperative history/i);
    expect(JSON.stringify(sampling!.exhibit)).toContain("Recorded before anesthesia");
    expect(JSON.stringify(sampling!.exhibit)).not.toMatch(/firm|thickening|separate from/i);
    expect(sampling!.explanation).toContain("Rectal sampling may also be indicated");
    expect(sampling!.choices.map((choice) => choice.timingProfileId)).toEqual([
      "timing.test.biopsy", "timing.test.mri", "timing.test.pathology_review",
    ]);
  });

  it("covers every exact assigned occurrence without borrowing another lane", () => {
    const program = JSON.parse(read("docs/research/question-intraop-program-20261112.json")) as {
      taxonomy: Array<typeof packet.assignment>;
      coverage: { liveCoverage: Array<{ recordId: string; nodeSha256: string }>; retainedCoverage: Array<{ recordId: string; nodeSha256: string }>; authoringDefinitions: Array<{ recordId: string; questionSha256: string }> };
    };
    expect(packet.assignment).toEqual(program.taxonomy.find((topic) => topic.id === "I09"));
    const assignedIds = [
      ...packet.assignment.existingRelatedBankNodes.map((row) => row.recordId),
      ...packet.assignment.retainedRecordIds,
      ...packet.assignment.authoringDefinitionRecordIds,
    ];
    expect(assignedIds).toHaveLength(62);
    expect(packet.audit.map((row) => row.inventoryRecordId).sort()).toEqual([...assignedIds].sort());
    expect(new Set(packet.audit.map((row) => row.inventoryRecordId)).size).toBe(62);
    const expected = new Map([
      ...program.coverage.liveCoverage.map((row) => [row.recordId, row.nodeSha256] as const),
      ...program.coverage.retainedCoverage.map((row) => [row.recordId, row.nodeSha256] as const),
      ...program.coverage.authoringDefinitions.map((row) => [row.recordId, row.questionSha256] as const),
    ]);
    for (const row of packet.audit) {
      expect(digest(row.definition), row.inventoryRecordId).toBe(expected.get(row.inventoryRecordId));
      expect(row.observedSourceSha256).toBe(row.beforeSha256);
      expect(row.beforeVersion).toBeTruthy();
      expect(row.reason.length).toBeGreaterThan(80);
      expect(row.verdict).toBe("Keep");
    }
  });

  it("preserves source files, older header/profile contexts and review receipts", () => {
    for (const pin of [...packet.inputProtection.sourceFilePins, ...packet.inputProtection.reviewFilePins]) {
      expect(sha(read(pin.path)), pin.path).toBe(pin.sha256);
    }
    expect(packet.retainedContextSnapshots).toHaveLength(32);
    expect(packet.retainedContextSnapshots.reduce((sum, row) => sum + row.contexts.length, 0)).toBe(48);
    for (const row of packet.retainedContextSnapshots) for (const context of row.contexts) {
      expect(digest(context.case)).toBe(context.caseSha256);
      expect(context.locators.length).toBeGreaterThan(0);
    }
    expect(packet.historicalHolds.heldUnkeyedCount).toBe(2);
    expect(packet.historicalHolds.applicablePriorHolds).toContain("n4-slot-OR11");
    expect(packet.historicalHolds.applicablePriorHolds).toContain("n4-slot-OR12");
    expect(packet.historicalHolds.priorTopicOwnerApprovals.some((hold) => hold.id === "review.n3.recurrent-fistula-continence-reserve.v3")).toBe(true);
  });

  it("freezes all eight accepted live nodes and the additional related low-tract PASS", () => {
    expect(packet.freezePreservation.liveReferences).toHaveLength(8);
    for (const frozen of packet.freezePreservation.liveReferences) {
      const currentCase = SYNTHETIC_CLINICAL_RELEASE.cases.find((clinicalCase) => clinicalCase.id === frozen.caseId)!;
      expect(currentCase, frozen.caseId).toBeTruthy();
      expect(digest(currentCase)).toBe(frozen.caseSha256);
      expect(digest(currentCase.decisionNodes.find((node) => node.id === frozen.nodeId))).toBe(frozen.nodeSha256);
      expect(frozen.reviewReferences.some((record) => record.verdict === "PASS")).toBe(true);
      expect(frozen.managerAcceptance).toBeTruthy();
      expect(frozen.clinicalApproval).toBeNull();
    }
    expect(packet.frozenReferences).toHaveLength(6);
    for (const frozen of packet.frozenReferences) expect(frozen.reconciledReviewVerdict).toBe("PASS");
    expect(packet.expandedCoverage).toHaveLength(1);
    const expanded = packet.expandedCoverage[0]!;
    expect(digest(SYNTHETIC_CLINICAL_RELEASE.cases.find((clinicalCase) => clinicalCase.id === expanded.caseId))).toBe(expanded.caseSha256);
    expect(packet.clinicalApprovalReceipts).toEqual([]);
  });

  it("keeps new meanings distinct from registered history and fresh supply", () => {
    expect(concepts).toHaveLength(3);
    expect(new Set(concepts.map((concept) => concept.id)).size).toBe(3);
    for (const concept of concepts) {
      expect(testedConceptSchema.safeParse(concept).success).toBe(true);
      expect(SYNTHETIC_CLINICAL_RELEASE.concepts.some((existing) => existing.id === concept.id)).toBe(false);
    }
    const existingIds = new Set(packet.registryHistory.map((record) => record.conceptId));
    for (const proposal of conceptProposals) {
      expect(proposal.conceptRelation).toBe("new_meaning");
      expect(proposal.previousConceptId).toBeNull();
      for (const related of proposal.relatedExistingConceptIds) expect(existingIds.has(related), related).toBe(true);
    }
    for (const clinicalCase of cases) expect(SYNTHETIC_CLINICAL_RELEASE.cases.some((existing) => existing.id === clinicalCase.id)).toBe(false);
    expect(integration.independentReview.preservedPassQuestionVariantIds).toEqual(packet.revisionRound1.passFreeze.map((record) => record.questionVariantId));
    expect(integration.independentReview.returnedRevisionsAwaitingReview).toHaveLength(2);
    expect(integration.managerAcceptance).toBeNull();
    expect(integration.admittedCaseIds).toEqual([]);
  });

  it("validates the strict current structures and one randomized key per node", () => {
    expect(cases).toHaveLength(2);
    expect(nodes).toHaveLength(3);
    expect(questions).toHaveLength(3);
    for (const clinicalCase of cases) expect(syntheticClinicalCaseSchema.safeParse(clinicalCase).success).toBe(true);
    for (const node of nodes) {
      expect(decisionNodeSchema.safeParse(node).success).toBe(true);
      expect(node.answerChoices).toHaveLength(3);
      expect(node.answerChoices.filter((choice) => choice.isCorrect)).toHaveLength(1);
      expect(new Set(node.answerChoices.map((choice) => choice.id)).size).toBe(3);
      expect(node.shuffleAnswers).toBe(true);
