function containsExact(value: unknown, expected: unknown, seen = new Set<unknown>()): boolean {
  if (!value || typeof value !== "object" || seen.has(value)) return false;
  seen.add(value);
  const expectedId = (expected as { id?: unknown }).id;
  if (typeof expectedId === "string" && (value as { id?: unknown }).id === expectedId
    && sha(value) === sha(expected)) return true;
  return Object.values(value).some(child => containsExact(child, expected, seen));
}

