        .toBe(sha(topic.HEMORRHAGE_REVIEWED_V1.concepts.find(c => c.id === frozen.conceptId)));
      expect(sha(topic.HEMORRHAGE_AUTHORING_CASES.find(row => row.clinicalCase.id === frozen.caseId)))
        .toBe(sha(packet.reviewRound1.reviewedBundle.authoringCases.find(row => row.clinicalCase.id === frozen.caseId)));
      expect(sha(topic.HEMORRHAGE_DRAFT_NODES.find(row => row.questionVariantId === frozen.questionVariantId)))
        .toBe(sha(packet.reviewRound1.reviewedBundle.draftItems.flatMap<ReviewedDraft>(item => item.nodes)
          .find(row => row.questionVariantId === frozen.questionVariantId)));
    }
    for (const old of topic.HEMORRHAGE_REVIEWED_V1.questions) {
      const q = topic.HEMORRHAGE_ALL_QUESTIONS.find(q => q.id === old.id)!;
      expect(q.conceptId).toBe(old.conceptId);
      expect(q.answerChoices.map(c => c.id)).toEqual(old.answerChoices.map(c => c.id));
      expect(q.answerChoices.find(c => c.isCorrect)!.id).toBe(old.answerChoices.find(c => c.isCorrect)!.id);
      if (!packet.reviewRound1.passFrozen.some(row => row.questionVariantId === q.id)) {
        expect(q.contentVersion).toBe("clinical.intraop.operative-hemorrhage-and-splenic-injury.2026-11-12.v1.r1");
        expect(sha(q)).not.toBe(sha(old));
      }
    }
    for (const old of topic.HEMORRHAGE_REVIEWED_V1.claims)
      expect(sha(topic.HEMORRHAGE_CLAIMS.find(c => c.id === old.id))).toBe(sha(old));
    for (const id of ["source.intraop.operative-hemorrhage.wses-liver-2020", "source.intraop.operative-hemorrhage.ball-2021"])
      expect(sha(topic.HEMORRHAGE_SOURCES.find(s => s.id === id)))
        .toBe(sha(topic.HEMORRHAGE_REVIEWED_V1.sources.find(s => s.id === id)));
    expect(syntheticClinicalReleaseSchema.safeParse({ ...topic.HEMORRHAGE_SOURCE_RELEASE,
      concepts: topic.HEMORRHAGE_REVIEWED_V1.concepts, cases: topic.HEMORRHAGE_REVIEWED_V1.cases }).success).toBe(true);
  });

  it("answers every review note, preserves quoted evidence and limits returned nodes to one attempt", () => {
    const reviewText = read(packet.reviewRound1.reviewPath);
    expect(createHash("sha256").update(reviewText).digest("hex")).toBe(packet.reviewRound1.reviewSha256);
    const review = JSON.parse(reviewText) as Array<{
      id: string; verdict: string; clarityIssues: string[];
      cues: Array<{ phrase: string; why: string }>; fairness: string[]; suggestions: string[];
    }>;
    const noteIds: string[] = [];
    for (const row of review) {
      const response = packet.reviewRound1.responses.find(r => r.questionVariantId === row.id)!;
      expect(response.originalVerdict).toBe(row.verdict);
      expect(response.attemptCount).toBe(row.verdict === "PASS" ? 0 : 1);
      for (const section of ["clarityIssues", "cues", "fairness", "suggestions"] as const) {
        row[section].forEach((note, index) => {
          const id = row.id + "::" + section + "[" + index + "]"; noteIds.push(id);
          const answer = response.notes.find(n => n.noteId === id)!;
          expect(answer.originalNote).toEqual(note); expect(answer.response.length).toBeGreaterThan(40);
          expect(answer.clinicalApproval).toBe(false);
          if (typeof note !== "string") expect(answer.quotedPhrase).toBe(note.phrase);
        });
      }
    }
    expect(noteIds).toHaveLength(53);
    expect(packet.reviewRound1.responses.flatMap(r => r.notes.map(n => n.noteId)).sort()).toEqual(noteIds.sort());
    expect(packet.reviewRound1.acceptanceHolds).toHaveLength(3);
    expect(packet.reviewRound1.responses.filter(r => r.originalVerdict !== "PASS").every(r => !r.independentPass)).toBe(true);
  });

  it("has zero raw cue findings across canonical, finite and prior-feedback contexts", () => {
    let contexts = 0;
    for (const item of topic.HEMORRHAGE_ITEMS) for (const draft of item.nodes) {
      const c = cases.find(c => c.id === item.caseId)!;
      const q = topic.HEMORRHAGE_ALL_QUESTIONS.find(q => q.id === draft.questionVariantId)!;
      const index = c.decisionNodes.findIndex(n => n.questionVariantId === q.id);
      const prior = index < 0 ? [] : c.decisionNodes.slice(0, index);
      for (const p of [null, ...c.approvedInstantiationProfiles!]) {
        const result = lintQuestion({
          variantId: q.id, caseId: c.id, profileId: p?.id ?? null,
          choices: q.answerChoices, rationales: q.answerChoices.map(a => ({ choiceId: a.id, text: a.rationale ?? a.distractorRationale })),
          fields: { chiefComplaint: p?.chiefComplaint ?? c.chiefComplaint, presentation: p?.presentation ?? c.presentation,
            currentUpdate: draft.currentUpdate, exhibit: draft.exhibit ? JSON.stringify(draft.exhibit) : "", stem: q.stem,
            priorVisibleSequence: prior.map(n => n.stem + " " +
              n.answerChoices.map(a => a.label + " " + a.rationale).join(" ") + " " + n.explanation).join(" ") },
        });
        expect(result.findings, draft.nodeId + " / " + (p?.id ?? "canonical")).toEqual([]); contexts++;
      }
    }
    expect(contexts).toBe(8); expect(packet.advisoryLint.linterVersion).toBe(LINTER_VERSION);
    expect(packet.advisoryLint.findings).toEqual([]);
  });
});

