const sha = (value: unknown) => createHash("sha256").update(beforeProgramBatch9AcceptanceSourceBytes(typeof value === "string" ? value : JSON.stringify(value))).digest("hex");
interface SavedContext {
  header: Record<string, unknown>; headerSha256: string; precedingNodes: unknown[];
