const digest = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const fileHash = (path: string) => createHash("sha256").update(read(path)).digest("hex");
const sourceModules: Record<string, unknown> = {
  "packages/clinical-content/src/question-topic-pediatric-neck-thoracic-gu-20261111.ts": ntg,
