  "packages/clinical-content/src/question-n4-accepted-20261110.ts": n4,
};
const resolveLocator = (locator: string) => {
  const [path, keys] = locator.split("#");
  let value = sourceModules[path!];
  for (const key of keys!.split(".")) value = (value as Record<string, unknown>)[key];
  return value;
};

