const sha = (value: unknown) => createHash("sha256").update(typeof value === "string" ? value : JSON.stringify(value)).digest("hex");
const packetPath = "docs/research/question-intraop-polypectomy-technique-and-bleeding-20261112.json";
interface BeforeRow {
  recordId: string; inventoryKind: string; conceptId: string; questionVariantId: string;
  nodeId?: string; questionSha256?: string; nodeSha256?: string;
  source: { file: string; export: string };
  exactDefinition: unknown; currentDefinitionMatch: boolean;
