    reviewedSnapshot: { I14_CASES: typeof authored.I14_CASES; I14_QUESTIONS: typeof authored.I14_QUESTIONS;
      I14_ITEMS: typeof authored.I14_ITEMS; I14_CONCEPTS: typeof authored.I14_CONCEPTS };
    frozenPass: Array<{ questionVariantId: string; nodeId: string; caseId: string;
      questionSha256: string; nodeSha256: string; caseHeaderSha256: string }>;
    noteResponses: Array<{ questionVariantId: string; category: string; index: number; note: unknown; response: string; status: string }>;
    attempts: Array<{ questionVariantId: string; attemptCount: number; beforeQuestionSha256: string; afterQuestionSha256: string }>;
