function objects(value: unknown, seen = new Set<object>(), output: Record<string, unknown>[] = []) {
  if (!value || typeof value !== "object" || seen.has(value)) return output;
  seen.add(value);
  if (!Array.isArray(value)) output.push(value as Record<string, unknown>);
  for (const child of Object.values(value)) if (child && typeof child === "object") objects(child, seen, output);
  return output;
}

