describe('Batch9 standalone salvage: polypectomy-technique-and-bleeding', () => {
  it('preserves every original export, historical packet field and source/document preimage', () => {
    const expectedExports = ['I14_SALVAGE', 'I14_SALVAGE_CASES', 'I14_SALVAGE_METADATA', 'I14_SALVAGE_PREVIEW_RELEASE', 'I14_SALVAGE_TIMING_ENTRIES'].sort();
    expect(Object.keys(salvageLane).filter(name => name.startsWith('I14_SALVAGE')).sort()).toEqual(expectedExports);
    const originalExports = Object.fromEntries(Object.entries(salvageLane).sort(([left], [right]) => left < right ? -1 : left > right ? 1 : 0).filter(([name]) => !name.startsWith('I14_SALVAGE')).map(([name, value]) => [name, value]));
    expect(salvageHash(originalExports)).toBe(salvageDraft.preservation.originalExportsSha256);
    const originalPacket = JSON.parse(salvageRead('docs/research/question-intraop-polypectomy-technique-and-bleeding-20261112.json')) as Record<string, unknown>;
    delete originalPacket.salvage;
    expect(salvageHash(originalPacket)).toBe(salvageDraft.preservation.originalPacketContentSha256);
