  });

  it('contains only each requested PASS decision with exact scored bytes and explicit final closure', () => {
    expect(salvageDraft.definitions.map(spec => spec.nodeId)).toEqual(["node.intraop.polypectomy.right-colon-defect-after-clearance.20261112.v1"]);
