import {beforeProgramBatch10AcceptanceSource} from "./question-program-batch10-acceptance-test-support";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import * as authored from "./question-intraop-suspicious-polyps-retrieval-and-tattoo-20261112";
import { answerChoiceTimingRegistryEntrySchema, validateSyntheticClinicalRelease } from "./schema";
import packet from "../../../docs/research/question-intraop-suspicious-polyps-retrieval-and-tattoo-20261112.json";
import ledger from "../../../docs/research/sources-question-intraop-suspicious-polyps-retrieval-and-tattoo-20261112.json";

const root = new URL("../../../", import.meta.url);
// Preserve every pre-acceptance exclusion against its exact pinned source epoch.
const read = (path: string) => beforeProgramBatch10AcceptanceSource(path, readFileSync(new URL(path, root), "utf8"));
const sha = (value: unknown) => createHash("sha256").update(typeof value === "string" ? value : JSON.stringify(value)).digest("hex");
function objects(value: unknown, seen = new Set<object>()): Record<string, unknown>[] {
  if (!value || typeof value !== "object" || seen.has(value)) return [];
  seen.add(value);
  return [value as Record<string, unknown>, ...Object.values(value).flatMap(v => objects(v, seen))];
}
type LintReport = { findings: unknown[] };

describe("I15 suspicious polyp retrieval and tattoo authoring sidecar", () => {
  it("audits every assigned occurrence and separates the existing held draft from scored verdict totals", () => {
    const inventory = JSON.parse(read("docs/research/question-intraop-program-20261112.json")) as {
      coverage: Record<string, Array<{ recordId: string; topicIds: string[] }>>;
    };
    const expected = ["liveCoverage", "retainedCoverage", "authoringDefinitions"].flatMap(key => inventory.coverage[key]!.filter(r => r.topicIds.includes("I15")).map(r => r.recordId));
    expect(packet.before.map(r => r.recordId)).toEqual(expected);
    expect(new Set(expected).size).toBe(45);
    expect(packet.audit.filter(r => r.verdict === "Keep")).toHaveLength(42);
    expect(packet.audit.filter(r => r.planningDisposition).map(r => r.recordId)).toEqual(["retained.292", "retained.296", "authoring.422"]);
    expect(packet.audit.every(r => r.verdict === "Keep" || r.verdict === null && r.planningDisposition)).toBe(true);
    expect(packet.counts).toMatchObject({ currentLive: 6, retainedDefinitions: 20, authoredDefinitions: 19, additiveRewrites: 0, replacementProposals: 0, newDecisions: 3 });
  });

  it("preserves all exact before definitions and retained header/profile contexts through their actual source exports", async () => {
    const modules = new Map<string, Record<string, unknown>>();
    const exports = new Map<string, Record<string, unknown>[]>();
    const exportedObjects = async (file: string, name: string) => {
      const key = `${file}:${name}`;
      if (!modules.has(file)) modules.set(file, await import(new URL(file, root).href) as Record<string, unknown>);
      if (!exports.has(key)) exports.set(key, objects(modules.get(file)![name]));
      return exports.get(key)!;
    };
    let contexts = 0;
    for (const r of packet.before) {
      const expected = r.questionSha256 ?? r.nodeSha256;
      expect(r.currentDefinitionMatch, r.recordId).toBe(true);
      expect(sha(r.exactDefinition), r.recordId).toBe(expected);
      expect((await exportedObjects(r.source.file, r.source.export)).some(v => v.id === (r.nodeId ?? r.questionVariantId) && sha(v) === expected), r.recordId).toBe(true);
      expect(packet.audit.find(a => a.recordId === r.recordId)?.beforeSha256).toBe(expected);
      for (const context of r.allSourceContexts) {
        contexts += 1;
        expect(sha(context.header)).toBe(context.headerSha256);
        for (const origin of context.origins) {
          const candidates = (await exportedObjects(origin.file, origin.export)).filter(v => Array.isArray(v.decisionNodes));
          expect(candidates.some(c => {
            const { decisionNodes, ...header } = c;
            const nodes = decisionNodes as Array<{ id: string }>;
            const index = nodes.findIndex(n => n.id === r.nodeId && sha(n) === r.nodeSha256);
            return index >= 0 && sha(header) === context.headerSha256 && sha(nodes.slice(0, index)) === sha(context.precedingNodes);
          }), `${r.recordId} ${origin.file}:${origin.export}`).toBe(true);
        }
      }
    }
    expect(contexts).toBe(31);
  }, 30_000);

  it("freezes the six actual accepted cases and keeps editorial PASS distinct from clinical approval", async () => {
    const { SYNTHETIC_CLINICAL_RELEASE: live } = await import("./synthetic-content");
    const { QUESTION_SHIP_MANIFEST: manifest } = await import("./question-ship-manifest");
    expect(packet.freeze.currentLive).toHaveLength(6);
    expect(packet.freeze.clinicalApprovals).toEqual([]);
    for (const pin of packet.freeze.currentLive) {
      const c = live.cases.find(c => c.id === pin.caseId)!;
      const n = c.decisionNodes.find(n => n.id === pin.nodeId)!;
      expect(sha(c)).toBe(pin.caseSha256);
      expect(sha(n)).toBe(pin.nodeSha256);
      expect(c).toEqual(pin.exactCurrentCase);
      expect(manifest.accepted.find(a => a.caseId === c.id && a.nodeId === n.id && a.questionVariantId === n.questionVariantId)).toEqual(pin.managerAcceptance);
      expect(pin.editorialReview?.verdict).toBe("PASS");
      expect(pin.clinicalApproval).toBeNull();
    }
    for (const receipt of packet.freeze.sourceReceiptChecks) for (const source of receipt.currentSourceFiles) {
      expect(source.matches).toBe(true);
      expect(sha(read(source.path))).toBe(source.receiptSha256);
    }
    for (const reference of packet.reviewReferences) expect(sha(read(reference.path))).toBe(reference.fileSha256);
    expect(authored.I15_QUESTIONS.every(q => q.reviewStatus === "needs_clinician_review" && q.lastClinicianReview === null && q.aiAssistedDrafting)).toBe(true);
  });

  it("uses strict normalized cases, new concepts and shuffled stable choice identities", () => {
    expect(validateSyntheticClinicalRelease(authored.I15_PREVIEW_RELEASE).cases).toHaveLength(3);
    expect(authored.I15_CASES.map(c => c.decisionNodes.length)).toEqual([1, 1, 1]);
    const oldConceptIds = new Set(packet.before.map(r => r.conceptId));
    const nodes = authored.I15_CASES.flatMap(c => c.decisionNodes);
    expect(new Set(nodes.map(n => n.id)).size).toBe(3);
    expect(new Set(nodes.flatMap(n => n.answerChoices.map(a => a.id))).size).toBe(9);
    for (const n of nodes) {
      const q = authored.I15_QUESTIONS.find(q => q.id === n.questionVariantId)!;
      expect(oldConceptIds.has(n.primaryConceptId)).toBe(false);
      expect(n.shuffleAnswers).toBe(true);
      expect(n.answerChoices).toHaveLength(3);
      expect(n.answerChoices.filter(a => a.isCorrect)).toHaveLength(1);
      expect(n.resultGateAfter).toBeNull();
      expect(n.answerChoices.every(a => a.serviceRequest === null)).toBe(true);
      expect(n.answerChoices.map(a => [a.id, a.label, a.isCorrect])).toEqual(q.answerChoices.map(a => [a.id, a.label, a.isCorrect]));
    }
    expect(authored.I15_AUTHORING_CONCEPTS.every(c => c.previousConceptId === null && c.reviewStatus === "needs_clinician_review")).toBe(true);
  });

  it("keeps every finite adult profile in the live source-patient context behind ENG-I01", () => {
    expect(authored.I15_CASE_REVIEWS).toHaveLength(3);
    for (const c of authored.I15_CASES) {
      expect(c).toMatchObject({ chiefComplaint: "Colonoscopy", requiredClinicalSetting: "endoscopy", earliestFacilityStage: 2, routineEligible: false, tutorialEligible: false });
      expect(c.requiredCapabilityIds).toEqual(["capability.endoscopy", "capability.periop_recovery"]);
      expect(c.pediatricProfile).toBeUndefined();
      expect(c.approvedInstantiationProfiles).toHaveLength(1);
      for (const profile of c.approvedInstantiationProfiles!) {
        expect(profile.prototypeDemographics).toEqual(c.prototypeDemographics);
        expect(profile.presentation).toBe(c.presentation);
        const rendered = profile.presentation.replaceAll("{patientName}", c.patientDisplayName);
        expect(rendered.startsWith(`${c.patientDisplayName},`)).toBe(true);
