function objectHashes(value: unknown) {
  const hashes = new Set<string>(), seen = new WeakSet<object>();
  function visit(v: unknown) {
    if (!v || typeof v !== 'object' || seen.has(v)) return;
    seen.add(v); hashes.add(hash(v));
    for (const child of Object.values(v)) visit(child);
  }
  visit(value);
  return hashes;
}

