interface AuditRow {
  recordId: string; caseId?: string; nodeId?: string; questionVariantId: string; conceptId: string;
  beforeVersion: string; beforeSha256: string; observedSha256: string; beforeDefinition: unknown;
  source: { file: string; export: string }; verdict: string; supplyDisposition: string;
  reviewReferences: Array<{ path: string; verdict: string }>; limitations: string[]; changedByWorker: boolean;
  retainedContexts: Array<{ caseId: string; caseSha256: string; header: Record<string, unknown>; visiblePrecedingNodes: unknown[] }>;
}
const audit = packet.audit as unknown as AuditRow[];
function objects(root: unknown): Record<string, unknown>[] {
  const seen = new Set<object>(); const out: Record<string, unknown>[] = [];
  function visit(v: unknown) {
    if (!v || typeof v !== "object" || seen.has(v)) return;
    seen.add(v); const obj = v as Record<string, unknown>; out.push(obj); Object.values(obj).forEach(visit);
  }
  visit(root); return out;
}

